<?php
namespace Modules\Ran\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class ProductionOrderRequest extends FormRequest {public function authorize():bool{return auth()->check();} public function rules():array{return ['order_date'=>'required|date','due_date'=>'nullable|date|after_or_equal:order_date','location_id'=>'required|integer','store_id'=>'required|integer','artisan_id'=>'nullable|integer','supplier_contact_id'=>'nullable|integer','customer_contact_id'=>'nullable|integer','priority'=>'required|in:low,normal,high,urgent','instructions'=>'nullable|string|max:5000','estimated_cost'=>'nullable|numeric|min:0','lines'=>'required|array|min:1','lines.*.item_id'=>'nullable|integer','lines.*.design_id'=>'nullable|integer','lines.*.description'=>'required|string|max:255','lines.*.planned_quantity'=>'required|numeric|min:0.0001','lines.*.planned_gross_weight'=>'nullable|numeric|min:0','lines.*.planned_net_weight'=>'nullable|numeric|min:0','lines.*.planned_stone_weight'=>'nullable|numeric|min:0','lines.*.wastage_percent'=>'nullable|numeric|min:0','lines.*.making_charge'=>'nullable|numeric|min:0'];}}
